export const P0 = [-36, -16, TOWN_Z + 1.0];                                        // parvis origin (top of the paving)
const TH = Math.atan2(RIVAL.x - P0[0], RIVAL.y - P0[1]);
export const L2W = (x, y, z = 0) => [P0[0] + x * Math.cos(TH) + y * Math.sin(TH), P0[1] - x * Math.sin(TH) + y * Math.cos(TH), P0[2] + z];

